import api from '../services/api';
import Calendar from '../components/Calendar';

const EMPTY_DISPO = {
  date_specifique: '',
  heure_debut: '09:00',
  heure_fin: '10:00',
  nb_max_etudiants: 1,
  mode_seance: 'presentiel', // nouveau champ
};

export default function Disponibilites() {
  const [dispos, setDispos] = useState([]);
  const [profile, setProfile] = useState(null); // profil prof pour le mode d'enseignement
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [newDispo, setNewDispo] = useState({ ...EMPTY_DISPO });
  const [submitting, setSubmitting] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(new Date());

  useEffect(() => {
    fetchAll();
  }, []);

  const fetchAll = async () => {
    try {
      const [resDispos, resProfile] = await Promise.all([
        api.get('/api/professeurs/me/disponibilites'),
        api.get('/api/professeurs/me'),
      ]);
      setDispos(resDispos.data ?? []);
      setProfile(resProfile.data ?? null);

      // Initialiser le mode_seance selon le profil
      const mode = resProfile.data?.mode_enseignement;
      setNewDispo(prev => ({
        ...prev,
        mode_seance: mode === 'les_deux' ? 'presentiel' : (mode || 'presentiel'),
      }));
    } catch (e) {
      console.error('Erreur chargement:', e.response?.data);
    } finally {
      setLoading(false);
    }
  };

  const fetchDispos = async () => {
    try {
      const res = await api.get('/api/professeurs/me/disponibilites');
      setDispos(res.data ?? []);
    } catch (e) {
      console.error('Erreur chargement dispos:', e.response?.data);
    }
  };

  const handleAdd = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      await api.post('/api/professeurs/me/disponibilites', {
        ...newDispo,
        nb_max_etudiants: parseInt(newDispo.nb_max_etudiants, 10),
      });
      setShowForm(false);
      const mode = profile?.mode_enseignement;
      setNewDispo({
        ...EMPTY_DISPO,
        mode_seance: mode === 'les_deux' ? 'presentiel' : (mode || 'presentiel'),
      });
      await fetchDispos();
      alert('✅ Séance ajoutée !');
    } catch (e) {
      alert('Erreur : ' + (e.response?.data?.detail || e.message));
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (id) => {
    if (!id || !window.confirm('Supprimer ce créneau ?')) return;
    try {
      await api.delete(`/api/professeurs/me/disponibilites/${id}`);
      setDispos(prev => prev.filter(d => d.id !== id));
    } catch (e) {
      alert('Erreur suppression : ' + (e.response?.data?.detail || e.message));
      await fetchDispos();
    }
  };

  // Calcule la durée en heures
  const getDuration = (debut, fin) => {
    if (!debut || !fin) return null;
    const [h1, m1] = debut.split(':').map(Number);
    const [h2, m2] = fin.split(':').map(Number);
    const diff = (h2 * 60 + m2) - (h1 * 60 + m1);
    if (diff <= 0) return null;
    return diff >= 60 ? `${Math.floor(diff / 60)}h${diff % 60 > 0 ? String(diff % 60).padStart(2, '0') : ''}` : `${diff}min`;
  };

  const getModeLabel = (mode) => {
    if (mode === 'en_ligne') return { icon: '🌐', label: 'En ligne', color: '#38bdf8', bg: 'rgba(56,189,248,0.12)' };
    if (mode === 'presentiel') return { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.12)' };
    return { icon: '🔀', label: mode, color: 'var(--text2)', bg: 'var(--surface2)' };
  };

  const profMode = profile?.mode_enseignement;
  const showModeChoice = profMode === 'les_deux';

  // Jours ayant des dispos pour le calendrier
  const availableDays = dispos
    .map(d => d.date_specifique ? new Date(d.date_specifique).getDate() : null)
    .filter(Boolean);

  // Grouper les dispos par date
  const grouped = dispos.reduce((acc, d) => {
    const key = d.date_specifique || 'Sans date';
    if (!acc[key]) acc[key] = [];
    acc[key].push(d);
    return acc;
  }, {});

  const inp = {
    background: 'var(--surface2)',
    border: '1px solid var(--border)',
    borderRadius: 10,
    color: 'var(--text)',
    padding: '10px 14px',
    fontSize: '.9rem',
    outline: 'none',
    width: '100%',
    boxSizing: 'border-box',
  };

  if (loading) return (
    <div style={{ padding: 50, textAlign: 'center', color: 'var(--text2)' }}>
      ⏳ Chargement...
    </div>
  );

  return (
    <div style={{ padding: 32, maxWidth: 1100, margin: '0 auto' }}>

      {/* HEADER */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 28 }}>
        <div>
          <h2 style={{ fontFamily: 'Syne', margin: 0, fontSize: '1.6rem' }}>🗓 Mes disponibilités</h2>
          <p style={{ color: 'var(--text2)', fontSize: '.85rem', marginTop: 4 }}>
            {dispos.length} séance{dispos.length !== 1 ? 's' : ''} planifiée{dispos.length !== 1 ? 's' : ''}
          </p>
        </div>

        {/* Infos mode enseignement */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          {profMode && (
            <div style={{
              display: 'flex', alignItems: 'center', gap: 8,
              padding: '8px 14px', borderRadius: 20,
              background: profMode === 'en_ligne' ? 'rgba(56,189,248,0.1)' : profMode === 'presentiel' ? 'rgba(67,233,123,0.1)' : 'rgba(108,99,255,0.1)',
              border: `1px solid ${profMode === 'en_ligne' ? 'rgba(56,189,248,0.3)' : profMode === 'presentiel' ? 'rgba(67,233,123,0.3)' : 'rgba(108,99,255,0.3)'}`,
              fontSize: '.82rem', fontWeight: 600,
              color: profMode === 'en_ligne' ? '#38bdf8' : profMode === 'presentiel' ? '#43e97b' : '#6c63ff',
            }}>
              {profMode === 'en_ligne' ? '🌐' : profMode === 'presentiel' ? '🏫' : '🔀'}
              <span>Mode : {profMode === 'en_ligne' ? 'En ligne' : profMode === 'presentiel' ? 'Présentiel' : 'Les deux'}</span>
            </div>
          )}
          <button
            onClick={() => setShowForm(true)}
            style={{
              background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)',
              color: '#fff', border: 'none', padding: '11px 22px',
              borderRadius: 12, fontWeight: 600, cursor: 'pointer',
              fontSize: '.9rem', display: 'flex', alignItems: 'center', gap: 8,
            }}
          >
            + Nouvelle séance
          </button>
        </div>
      </div>

      {/* STATS RAPIDES */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 16, marginBottom: 28 }}>
        {[
          { icon: '📅', val: dispos.length, lbl: 'Séances planifiées', color: '#6c63ff', bg: 'rgba(108,99,255,.1)' },
          { icon: '👥', val: dispos.reduce((s, d) => s + (d.nb_max_etudiants || 0), 0), lbl: 'Places totales', color: '#43e97b', bg: 'rgba(67,233,123,.1)' },
          { icon: '📊', val: dispos.reduce((s, d) => s + (d.nb_inscrits || 0), 0), lbl: 'Inscrits total', color: '#f59e0b', bg: 'rgba(245,158,11,.1)' },
        ].map(s => (
          <div key={s.lbl} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: '16px 20px', display: 'flex', alignItems: 'center', gap: 14 }}>
            <div style={{ width: 44, height: 44, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem' }}>{s.icon}</div>
            <div>
              <div style={{ fontFamily: 'Syne', fontSize: '1.6rem', fontWeight: 800, color: s.color }}>{s.val}</div>
              <div style={{ fontSize: '.78rem', color: 'var(--text2)' }}>{s.lbl}</div>
            </div>
          </div>
        ))}
      </div>

      {/* GRILLE PRINCIPALE */}
      <div style={{ display: 'grid', gridTemplateColumns: '1.3fr 0.7fr', gap: 24 }}>

        {/* LISTE DES SÉANCES */}
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
          <h3 style={{ marginBottom: 20, marginTop: 0 }}>📋 Séances planifiées</h3>

          {dispos.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '40px 20px', color: 'var(--text2)' }}>
              <div style={{ fontSize: '2.5rem', marginBottom: 12 }}>📭</div>
              <div style={{ fontWeight: 600, marginBottom: 6 }}>Aucune séance planifiée</div>
              <div style={{ fontSize: '.82rem' }}>Cliquez sur "+ Nouvelle séance" pour commencer</div>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {Object.entries(grouped)
                .sort(([a], [b]) => a.localeCompare(b))
                .map(([date, seances]) => (
                  <div key={date}>
                    {/* Séparateur date */}
                    <div style={{ fontSize: '.75rem', fontWeight: 700, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.08em', marginBottom: 8, marginTop: 4 }}>
                      📆 {date !== 'Sans date' ? new Date(date + 'T00:00:00').toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) : 'Sans date'}
                    </div>

                    {seances.map(d => {
                      const modeInfo = getModeLabel(d.mode_seance || profMode);
                      const duration = getDuration(d.heure_debut?.slice(0, 5), d.heure_fin?.slice(0, 5));
                      const pct = d.nb_max_etudiants > 0 ? Math.round((d.nb_inscrits / d.nb_max_etudiants) * 100) : 0;

                      return (
                        <div key={d.id} style={{
                          background: 'var(--surface2)', padding: '14px 16px',
                          borderRadius: 14, border: '1px solid var(--border)',
                          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                          marginBottom: 8,
                          borderLeft: `3px solid ${modeInfo.color}`,
                        }}>
                          <div style={{ flex: 1 }}>
                            {/* Horaire + durée */}
                            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 6 }}>
                              <span style={{ fontWeight: 700, color: 'var(--accent)', fontSize: '.95rem' }}>
                                🕒 {d.heure_debut?.slice(0, 5)} – {d.heure_fin?.slice(0, 5)}
                              </span>
                              {duration && (
                                <span style={{ fontSize: '.72rem', background: 'rgba(108,99,255,0.15)', color: '#6c63ff', padding: '2px 8px', borderRadius: 20, fontWeight: 600 }}>
                                  {duration}
                                </span>
                              )}
                            </div>

                            {/* Mode séance */}
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
                              <span style={{ fontSize: '.75rem', fontWeight: 700, padding: '3px 10px', borderRadius: 20, background: modeInfo.bg, color: modeInfo.color }}>
                                {modeInfo.icon} {modeInfo.label}
                              </span>
                            </div>

                            {/* Barre de capacité */}
                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                              <span style={{ fontSize: '.75rem', color: 'var(--text2)', whiteSpace: 'nowrap' }}>
                                👥 {d.nb_inscrits}/{d.nb_max_etudiants}
                              </span>
                              <div style={{ flex: 1, height: 5, background: 'var(--border)', borderRadius: 3, overflow: 'hidden', maxWidth: 120 }}>
                                <div style={{
                                  height: '100%', borderRadius: 3,
                                  background: pct >= 100 ? '#ff6584' : pct >= 70 ? '#f59e0b' : '#43e97b',
                                  width: `${Math.min(pct, 100)}%`, transition: 'width .3s',
                                }} />
                              </div>
                              <span style={{ fontSize: '.72rem', color: pct >= 100 ? '#ff6584' : 'var(--text2)' }}>
                                {pct >= 100 ? 'Complet' : `${100 - pct}% libre`}
                              </span>
                            </div>
                          </div>

                          <button
                            onClick={() => handleDelete(d.id)}
                            style={{
                              background: 'rgba(255,101,132,0.1)', color: '#ff6584',
                              border: '1px solid rgba(255,101,132,0.2)',
                              padding: '8px 10px', borderRadius: 10, cursor: 'pointer',
                              fontSize: '.9rem', marginLeft: 12, flexShrink: 0,
                            }}
                            title="Supprimer"
                          >🗑</button>
                        </div>
                      );
                    })}
                  </div>
                ))}
            </div>
          )}
        </div>

        {/* CALENDRIER */}
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24, alignSelf: 'start', position: 'sticky', top: 80 }}>
          <h3 style={{ marginBottom: 20, marginTop: 0 }}>📅 Calendrier</h3>
          <Calendar available={availableDays} />
          <div style={{ marginTop: 16, display: 'flex', flexDirection: 'column', gap: 6 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: '.78rem', color: 'var(--text2)' }}>
              <div style={{ width: 10, height: 10, borderRadius: '50%', background: '#43e97b' }} />
              Jour avec séance planifiée
            </div>
          </div>
        </div>
      </div>

      {/* ===== MODAL CRÉATION SÉANCE ===== */}
      {showForm && (
        <div style={{
          position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)',
          zIndex: 2000, display: 'flex', alignItems: 'center', justifyContent: 'center',
          padding: 20,
        }}>
          <div style={{
            background: 'var(--surface)', padding: 32, borderRadius: 24,
            width: '100%', maxWidth: 480, border: '1px solid var(--border)',
            maxHeight: '90vh', overflowY: 'auto',
          }}>
            {/* Header modal */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
              <h3 style={{ margin: 0, fontFamily: 'Syne', fontSize: '1.2rem' }}>📅 Nouvelle séance</h3>
              <button
                onClick={() => { setShowForm(false); const mode = profile?.mode_enseignement; setNewDispo({ ...EMPTY_DISPO, mode_seance: mode === 'les_deux' ? 'presentiel' : (mode || 'presentiel') }); }}
                style={{ width: 32, height: 32, borderRadius: 8, background: 'var(--surface2)', border: '1px solid var(--border)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text)', fontSize: '1rem' }}
              >✕</button>
            </div>

            <form onSubmit={handleAdd} style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>

              {/* 1. DATE */}
              <div>
                <label style={{ fontSize: '.82rem', fontWeight: 700, color: 'var(--text2)', display: 'block', marginBottom: 8, textTransform: 'uppercase', letterSpacing: '.06em' }}>
                  📆 Date de la séance
                </label>
                <input
                  type="date"
                  style={{ ...inp }}
                  required
                  min={new Date().toISOString().split('T')[0]}
                  value={newDispo.date_specifique}
                  onChange={e => setNewDispo({ ...newDispo, date_specifique: e.target.value })}
                />
                {/* Affichage jour */}
                {newDispo.date_specifique && (
                  <div style={{ marginTop: 6, fontSize: '.8rem', color: '#6c63ff', fontWeight: 600 }}>
                    📍 {new Date(newDispo.date_specifique + 'T00:00:00').toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
                  </div>
                )}
              </div>

              {/* 2. HORAIRES */}
              <div>
                <label style={{ fontSize: '.82rem', fontWeight: 700, color: 'var(--text2)', display: 'block', marginBottom: 8, textTransform: 'uppercase', letterSpacing: '.06em' }}>
                  🕒 Horaires
                </label>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                  <div>
                    <div style={{ fontSize: '.75rem', color: 'var(--text2)', marginBottom: 5 }}>Heure de début</div>
                    <input
                      type="time"
                      style={{ ...inp }}
                      required
                      value={newDispo.heure_debut}
                      onChange={e => setNewDispo({ ...newDispo, heure_debut: e.target.value })}
                    />
                  </div>
                  <div>
                    <div style={{ fontSize: '.75rem', color: 'var(--text2)', marginBottom: 5 }}>Heure de fin</div>
                    <input
                      type="time"
                      style={{ ...inp }}
                      required
                      value={newDispo.heure_fin}
                      onChange={e => setNewDispo({ ...newDispo, heure_fin: e.target.value })}
                    />
                  </div>
                </div>
                {/* Affichage durée calculée */}
                {(() => {
                  const dur = getDuration(newDispo.heure_debut, newDispo.heure_fin);
                  return dur ? (
                    <div style={{ marginTop: 8, display: 'flex', alignItems: 'center', gap: 6, fontSize: '.8rem' }}>
                      <span style={{ background: 'rgba(108,99,255,0.15)', color: '#6c63ff', padding: '3px 10px', borderRadius: 20, fontWeight: 700 }}>
                        ⏱ Durée : {dur}
                      </span>
                    </div>
                  ) : newDispo.heure_debut && newDispo.heure_fin ? (
                    <div style={{ marginTop: 8, fontSize: '.8rem', color: '#ff6584' }}>
                      ⚠️ L'heure de fin doit être après l'heure de début
                    </div>
                  ) : null;
                })()}
              </div>

              {/* 3. MODE D'ENSEIGNEMENT (seulement si profil = "les_deux") */}
              {showModeChoice && (
                <div>
                  <label style={{ fontSize: '.82rem', fontWeight: 700, color: 'var(--text2)', display: 'block', marginBottom: 8, textTransform: 'uppercase', letterSpacing: '.06em' }}>
                    🎓 Mode de cette séance
                  </label>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                    {[
                      { value: 'en_ligne', icon: '🌐', label: 'En ligne', color: '#38bdf8', bg: 'rgba(56,189,248,0.1)', border: 'rgba(56,189,248,0.35)' },
                      { value: 'presentiel', icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.1)', border: 'rgba(67,233,123,0.35)' },
                    ].map(m => {
                      const active = newDispo.mode_seance === m.value;
                      return (
                        <div
                          key={m.value}
                          onClick={() => setNewDispo({ ...newDispo, mode_seance: m.value })}
                          style={{
                            padding: '14px 16px', borderRadius: 14, cursor: 'pointer',
                            border: active ? `2px solid ${m.border}` : '2px solid var(--border)',
                            background: active ? m.bg : 'var(--surface2)',
                            textAlign: 'center', transition: 'all .18s',
                          }}
                        >
                          <div style={{ fontSize: '1.5rem', marginBottom: 4 }}>{m.icon}</div>
                          <div style={{ fontWeight: 700, fontSize: '.88rem', color: active ? m.color : 'var(--text)' }}>
                            {m.label}
                          </div>
                          {active && (
                            <div style={{ marginTop: 4, fontSize: '.7rem', color: m.color }}>✓ Sélectionné</div>
                          )}
                        </div>
                      );
                    })}
                  </div>

                  {/* Affichage du tarif correspondant */}
                  {newDispo.mode_seance === 'en_ligne' && profile?.tarif_en_ligne && (
                    <div style={{ marginTop: 10, padding: '8px 14px', background: 'rgba(56,189,248,0.07)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 10, fontSize: '.8rem', color: '#38bdf8', fontWeight: 600 }}>
                      💰 Tarif appliqué : {profile.tarif_en_ligne} DT/h (en ligne)
                    </div>
                  )}
                  {newDispo.mode_seance === 'presentiel' && profile?.tarif_presentiel && (
                    <div style={{ marginTop: 10, padding: '8px 14px', background: 'rgba(67,233,123,0.07)', border: '1px solid rgba(67,233,123,0.2)', borderRadius: 10, fontSize: '.8rem', color: '#43e97b', fontWeight: 600 }}>
                      💰 Tarif appliqué : {profile.tarif_presentiel} DT/h (présentiel)
                    </div>
                  )}
                </div>
              )}

              {/* Si mode fixe (pas les_deux), afficher juste le mode en lecture seule */}
              {!showModeChoice && profMode && (
                <div>
                  <label style={{ fontSize: '.82rem', fontWeight: 700, color: 'var(--text2)', display: 'block', marginBottom: 8, textTransform: 'uppercase', letterSpacing: '.06em' }}>
                    🎓 Mode d'enseignement
                  </label>
                  <div style={{
                    padding: '12px 16px', borderRadius: 12,
                    background: profMode === 'en_ligne' ? 'rgba(56,189,248,0.08)' : 'rgba(67,233,123,0.08)',
                    border: `1px solid ${profMode === 'en_ligne' ? 'rgba(56,189,248,0.25)' : 'rgba(67,233,123,0.25)'}`,
                    display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                  }}>
                    <span style={{ fontWeight: 700, color: profMode === 'en_ligne' ? '#38bdf8' : '#43e97b', fontSize: '.9rem' }}>
                      {profMode === 'en_ligne' ? '🌐 En ligne' : '🏫 Présentiel'}
                    </span>
                    {((profMode === 'en_ligne' && profile?.tarif_en_ligne) || (profMode === 'presentiel' && profile?.tarif_presentiel)) && (
                      <span style={{ fontSize: '.8rem', color: 'var(--text2)', fontWeight: 600 }}>
                        💰 {profMode === 'en_ligne' ? profile.tarif_en_ligne : profile.tarif_presentiel} DT/h
                      </span>
                    )}
                  </div>
                </div>
              )}

              {/* 4. NOMBRE MAX D'ÉTUDIANTS */}
              <div>
                <label style={{ fontSize: '.82rem', fontWeight: 700, color: 'var(--text2)', display: 'block', marginBottom: 8, textTransform: 'uppercase', letterSpacing: '.06em' }}>
                  👥 Capacité maximale
                </label>
                {/* Sélection rapide */}
                <div style={{ display: 'flex', gap: 8, marginBottom: 10 }}>
                  {[1, 2, 3, 5, 10].map(n => (
                    <button
                      key={n} type="button"
                      onClick={() => setNewDispo({ ...newDispo, nb_max_etudiants: n })}
                      style={{
                        flex: 1, padding: '8px 0', borderRadius: 10, cursor: 'pointer',
                        border: newDispo.nb_max_etudiants === n ? '2px solid var(--accent)' : '2px solid var(--border)',
                        background: newDispo.nb_max_etudiants === n ? 'rgba(108,99,255,0.15)' : 'var(--surface2)',
                        color: newDispo.nb_max_etudiants === n ? '#6c63ff' : 'var(--text)',
                        fontWeight: 700, fontSize: '.85rem', transition: 'all .15s',
                      }}
                    >
                      {n === 1 ? '👤 1' : `${n}`}
                    </button>
                  ))}
                </div>
                {/* Ou saisie manuelle */}
                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <input
                    type="number" min="1" max="50"
                    style={{ ...inp }}
                    placeholder="Ou saisir un nombre..."
                    value={newDispo.nb_max_etudiants}
                    onChange={e => setNewDispo({ ...newDispo, nb_max_etudiants: parseInt(e.target.value) || 1 })}
                  />
                  <span style={{ color: 'var(--text2)', whiteSpace: 'nowrap', fontSize: '.85rem' }}>
                    étudiant{newDispo.nb_max_etudiants > 1 ? 's' : ''}
                  </span>
                </div>
                {newDispo.nb_max_etudiants > 1 && (
                  <div style={{ marginTop: 6, fontSize: '.78rem', color: '#f59e0b' }}>
                    ℹ️ Séance de groupe ({newDispo.nb_max_etudiants} étudiants max)
                  </div>
                )}
              </div>

              {/* RÉCAPITULATIF */}
              {newDispo.date_specifique && getDuration(newDispo.heure_debut, newDispo.heure_fin) && (
                <div style={{ background: 'rgba(108,99,255,0.07)', border: '1px solid rgba(108,99,255,0.2)', borderRadius: 14, padding: 16 }}>
                  <div style={{ fontWeight: 700, fontSize: '.82rem', color: '#6c63ff', marginBottom: 10, textTransform: 'uppercase', letterSpacing: '.06em' }}>
                    📋 Récapitulatif
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 5, fontSize: '.85rem' }}>
                    <div>📆 {new Date(newDispo.date_specifique + 'T00:00:00').toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long' })}</div>
                    <div>🕒 {newDispo.heure_debut} → {newDispo.heure_fin} ({getDuration(newDispo.heure_debut, newDispo.heure_fin)})</div>
                    <div>{newDispo.mode_seance === 'en_ligne' ? '🌐 En ligne' : '🏫 Présentiel'}</div>
                    <div>👥 {newDispo.nb_max_etudiants} étudiant{newDispo.nb_max_etudiants > 1 ? 's' : ''} max</div>
                  </div>
                </div>
              )}

              {/* BOUTONS */}
              <div style={{ display: 'flex', gap: 12, marginTop: 4 }}>
                <button
                  type="submit"
                  disabled={submitting || !getDuration(newDispo.heure_debut, newDispo.heure_fin)}
                  style={{
                    flex: 2, padding: '13px',
                    background: submitting || !getDuration(newDispo.heure_debut, newDispo.heure_fin)
                      ? 'var(--border)'
                      : 'linear-gradient(135deg,#6c63ff,#8b5cf6)',
                    color: '#fff', border: 'none', borderRadius: 12,
                    fontWeight: 700, cursor: submitting ? 'not-allowed' : 'pointer',
                    fontSize: '.9rem',
                  }}
                >
                  {submitting ? '⏳ Création...' : '✅ Créer la séance'}
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setShowForm(false);
                    const mode = profile?.mode_enseignement;
                    setNewDispo({ ...EMPTY_DISPO, mode_seance: mode === 'les_deux' ? 'presentiel' : (mode || 'presentiel') });
                  }}
                  style={{ flex: 1, background: 'var(--surface2)', color: 'var(--text)', border: '1px solid var(--border)', padding: '13px', borderRadius: 12, cursor: 'pointer', fontWeight: 600 }}
                >
                  Annuler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
